package com.cpf.education.online.securityaudit.controller;
import com.cpf.education.online.securityaudit.dto.MemberSecurityCommand;import com.cpf.education.online.securityaudit.service.MemberSecurityService;import com.cpf.foundation.execution.api.CpfOnlineTransaction;import com.cpf.security.api.annotation.CpfPermission;import com.cpf.web.api.CpfController;import io.swagger.v3.oas.annotations.Operation;import java.util.Map;import org.springframework.web.bind.annotation.*;
/** 보안·감사 교육 예제의 Controller 역할과 CPF 표준 사용 경계를 보여줍니다. */
@CpfController @RequestMapping("/edu/online/member-security") public class MemberSecurityController {private final MemberSecurityService service;public MemberSecurityController(MemberSecurityService s){service=s;}@PostMapping @CpfPermission("hasAuthority('MEMBER_READ')") @Operation(operationId="EDU_SECURE_MEMBER_LOOKUP",summary="Security·Permission·Audit 거래") @CpfOnlineTransaction(operationId="EDU_SECURE_MEMBER_LOOKUP",name="Security·Permission·Audit 거래",description="Spring Method Security 의미를 따르는 CPF 권한 Annotation과 CPF Audit/Masking을 사용한다.") public Map<String,String> read(@RequestBody MemberSecurityCommand c){return service.read(c);}}
